const fs = await import('node:fs/promises');
const S = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts";
const P2 = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具";
const master = JSON.parse(await fs.readFile(S+"\\_GIG_MASTER.json","utf8"));
const cn = JSON.parse(await fs.readFile(S+"\\_CN_GIG_RESULT.json","utf8"));

// 把中文平台替换/补充进 master
const cnGood = cn.filter(o=>String(o.status).includes("✅")).map(o=>({
  name:o.name, host:o.host.replace(/^www\./,""), url:o.url, group:"能看到活", verdict:o.status, cards:o.projHits||0, note:"中文平台 proj="+o.projHits
}));

// 移除旧的中文条目（避免重复），再加新的
const oldCnGroups = ["🇨🇳 中文接单"];
const kept = {};
for (const [cat, items] of Object.entries(master.groups)) {
  if (oldCnGroups.includes(cat)) continue;
  kept[cat] = items.filter(it => !["zbj.com","proginn.com","shixian.com","yuanjisong.com","tezign.com","epwk.com","zb.oschina.net"].includes(String(it.host).toLowerCase()));
}
kept["🇨🇳 中文接单（实测）"] = cnGood;

// 重新按 host 去重
const seen = new Set();
const finalGroups = {};
for (const [cat, items] of Object.entries(kept)) {
  const out = [];
  for (const it of items) {
    const h = String(it.host).toLowerCase().replace(/^www\./,"");
    if (seen.has(h)) continue;
    seen.add(h);
    out.push(it);
  }
  if (out.length) finalGroups[cat] = out;
}
const total = Object.values(finalGroups).reduce((s,g)=>s+g.length,0);
await fs.writeFile(S+"\\_GIG_MASTER_FINAL.json", JSON.stringify({total, groups:finalGroups},null,1), "utf8");
return { total, groups: Object.entries(finalGroups).map(([k,v])=>k+":"+v.length) };
